var TOPICS=[{"brief":"Basic arithmetic calculators — the four-banger refined — handle everyday math with variations in display, power, and durability for every pocket and desk.","examples":["A shopkeeper's desktop printing calculator tapes every transaction — the paper audit trail for the day's cash.","A student's basic exam calculator: big keys, solar power, square-root key — everything allowed, nothing banned."],"history":["The four-banger commoditized in the 1970s price wars; printing calculators kept the mechanical adding-machine's tape.","Exam rules sustain the category — simplicity is a feature when only basics are allowed."],"points":["Core: add, subtract, multiply, divide, percent, square root — the everyday set.","Displays: 8-12 digits, some with commas — readability for money math.","Printing models: paper tapes for audit trails — retail and accounting.","Power: solar, battery, or dual — the desk tool that never dies.","Variants: pocket, desktop, jumbo-key, and waterproof — one for every hand."],"qa":[["What is the difference from a scientific calculator?","Scope: basics do arithmetic; scientific adds trig, logs, and stats — buy the tier you need."],["Why do printing calculators survive?","Audit trails: the tape proves the day's transactions — required in some cash businesses."],["Which basic for exams?","The simplest allowed — check the list; extra functions can disqualify."]],"title":"Basic Arithmetic Calculators","uses":["Daily math: the pocket and desk standard.","Exams: the allowed simplicity.","Cash businesses: printed audit trails."]},{"brief":"Scientific calculators are the STEM workhorse — trig, logs, stats, and constants — with display and entry systems that define the experience.","examples":["A chemistry student's two-line display shows the entered expression and the result — errors caught before evaluating.","An engineer's solver key finds roots of equations numerically — the field math machine."],"history":["HP-35 (1972) invented the category; TI-30 (1976) democratized it; multi-line displays (1990s) made entry visual.","Exam approval lists now shape every model's feature set."],"points":["Functions: trig, hyperbolic, logs, exponentials, powers, roots, factorials, and constants.","Entry: algebraic with textbook display on modern models — math as written.","Statistics: 1- and 2-variable, regressions, distributions — the stats course built in.","Memory: variables A-F plus Ans — chaining multi-step problems.","Solar/battery dual power and exam-approved designs — the classroom standard."],"qa":[["What should a student look for?","Exam approval first, then textbook display, then the stats functions the course needs."],["What is textbook display?","Math shown as written — fractions stacked, roots with radicals — not linear code."],["How do engineers use the solver?","Entering equations and solving numerically for any variable — the field equation-solver."]],"title":"Scientific Calculators","uses":["STEM classes: the required tool.","Engineering: field computation.","Labs: stats and conversions."]},{"brief":"Graphing calculators visualize mathematics — plotting, tables, and solvers — the approved visual lab for exams and classrooms.","examples":["A calculus student watches the derivative trace along the curve — the concept made visible.","A statistics class compares regression models on real data — the fit quality on screen."],"history":["Casio fx-7000G (1985) first; TI-81/83/84 (1990s-2000s) owned US classrooms; color screens (2010s) modernized.","Longevity comes from exam-board certification — the TI-84's moat."],"points":["Graphing: multiple functions, trace, zoom, intersection/zero/maximum finders.","Tables: numeric x/y exploration alongside graphs.","Statistics: plots, regressions, inference — the stats curriculum on-device.","Programming: TI-BASIC and now Python — automation and first code.","CAS vs non-CAS: symbolic algebra models exist but are banned on many exams — know the line."],"qa":[["What is the difference between graphing and scientific?","Visualization: graphing plots and analyzes functions; scientific computes values."],["Why is the TI-84 still standard?","Exam certification plus teacher familiarity — the classroom ecosystem."],["Should you get CAS?","Only if allowed — CAS does symbolic algebra, which many exams prohibit."]],"title":"Graphing Calculators","uses":["Math classes: visualizing functions.","Standardized tests: the approved aid.","Statistics: on-device inference."]},{"brief":"Financial calculators speak money-over-time — TVM, amortization, NPV/IRR — the banker's and real-estate professional's instrument.","examples":["A mortgage broker compares loan offers: payment, total interest, and APR side by side.","An analyst runs IRR on project cash flows — the investment decision in one function."],"history":["HP 12C (1981): RPN, gold keys, still manufactured — finance's icon.","TVM standardization made financial math portable across careers."],"points":["TVM keys: N, I/Y, PV, PMT, FV — the five-variable money machine.","Amortization: per-period interest/principal splits — the loan's anatomy.","Cash-flow analysis: NPV, IRR, NFV — investment decisions quantified.","Bonds: price, yield, accrued interest — fixed-income math.","Conventions: BEGIN/END modes, day-count — the details that change answers."],"qa":[["What makes a calculator financial?","TVM keys plus cash-flow, amortization, and bond functions — money-over-time as hardware."],["Why is the HP 12C legendary?","Unchanged since 1981: RPN, durability, and the exact keystrokes finance learned on."],["What is BEGIN vs END mode?","Whether payments occur at period start (leases) or end (loans) — the mode changes every answer."]],"title":"Financial Calculators","uses":["Banking: loan structuring.","Real estate: mortgage math.","Investing: cash-flow analysis."]},{"brief":"Printing and display calculators serve cash businesses — tapes for records, big keys for speed, durability for decades.","examples":["A market stall's printing calculator tapes 200 sales — the day's record in one roll.","An accountant's 12-digit desktop with comma markers: the tax-season workhorse."],"history":["Descendants of mechanical adding machines — the crank became keys, the mechanism became chips.","The tape endures where records matter."],"points":["Printing: ink-ribbon tapes of every entry — the audit trail.","Heavy-duty keys: rated for millions of presses — the daily driver.","Large displays: 12-14 digits with thousand separators — money made readable.","Tax and currency keys: dedicated functions for the shop's math.","Dual power and tilt displays — the countertop fixture."],"qa":[["Why print when screens show the answer?","Records: the tape is the transaction log — proof for the till and the auditor."],["What is a tax key?","A dedicated key applying the programmed tax rate — one press for tax-inclusive pricing."],["How long do they last?","Decades — the simple, rugged design outlives generations of fancier devices."]],"title":"Printing and Display Calculators","uses":["Retail: transaction tapes.","Accounting: heavy daily arithmetic.","Cash handling: auditable totals."]},{"brief":"Programmable calculators capture procedures — keystroke programs and real languages — automating professional math in the field.","examples":["A surveyor replays a traverse program at each station — coordinates from angles and distances.","An engineer automates a 30-step beam check — new inputs, instant answers."],"history":["HP-65 (1974): the first programmable handheld; magnetic cards stored programs.","Python on modern calculators continues the tradition legitimately."],"points":["Keystroke programming: record and replay — the original macro.","Storage registers and branching — real programs, not just sequences.","Modern: Python and TI-BASIC on current models — actual languages.","Exam status: programmables are often restricted — memory must clear.","The legacy: a generation learned algorithms on calculators before computers."],"qa":[["What could early programmables do?","Replay keystroke sequences with branching — automating field calculations."],["Why are they exam-restricted?","Stored programs could hold formulas and notes — test security."],["Do modern calculators still program?","Yes — Python on current models is the legitimate successor."]],"title":"Programmable Calculators","uses":["Field work: surveying and engineering automation.","Education: first programming.","Repetition: procedures captured once."]},{"brief":"CAS calculators do symbolic mathematics — algebra, calculus, exact forms — a computer algebra system in the hand.","examples":["A CAS factors x²−5x+6 into (x−2)(x−3) symbolically — not a decimal, the exact form.","A calculus student differentiates symbolically and checks by hand — the tutor that shows exact answers."],"history":["TI-92 (1995) brought Derive's CAS handheld; HP 48/49 offered RPL symbolic; Nspire CAS continues.","Exam boards mostly ban CAS — symbolic power is the line."],"points":["Symbolic: exact fractions, radicals, factored forms — not decimals.","Calculus: symbolic differentiation, integration, limits, series.","Equation solving: exact solutions where they exist.","The exam line: most standardized tests ban CAS — check before buying.","Pedagogy debate: tool for exploration vs crutch — the ongoing argument."],"qa":[["What is CAS?","Computer Algebra System — symbolic math: exact forms, not numeric approximations."],["Why are CAS calculators banned on many exams?","They do the algebra the test measures — symbolic manipulation is the skill being tested."],["When is CAS appropriate?","Exploration and verification in learning; professional symbolic work — where understanding, not testing, is the goal."]],"title":"CAS Calculators","uses":["Advanced math: symbolic exploration.","Engineering: exact forms.","Learning: checking hand work."]},{"brief":"RPN calculators — HP's stack-based entry — trade familiarity for efficiency: operators after operands, intermediates always visible.","examples":["An engineer's chain: 12 ENTER 7 + 5 × — no parentheses, no retyping.","A surveyor accumulates traverse legs on the stack — each result feeding the next."],"history":["HP-35 (1972) made RPN famous; the HP 12C keeps it alive in finance.","The devoted minority never switched — efficiency compounds."],"points":["Stack (X,Y,Z,T): the visible scratch paper — operands waiting for operators.","ENTER separates entries; operators consume the stack top.","No equals key, no parentheses — expressions evaluate inside-out.","Efficiency: fewer keystrokes for chained real-world calculations.","Learning curve: the investment — algebraic thinkers need retraining."],"qa":[["How do you add 3+4 in RPN?","3 ENTER 4 + — the stack holds both, + consumes them."],["Why do fans claim it's faster?","Intermediates stay on the stack — long chains need no parentheses or re-entry."],["Is RPN still relevant?","In finance (12C) and engineering niches — plus emulators and phone apps."]],"title":"RPN Calculators","uses":["Engineering: chained calculations.","Finance: the 12C standard.","Enthusiasts: the efficient minority."]},{"brief":"Construction calculators speak the trade — feet, inches, fractions — with built-in right-triangle and material functions.","examples":["Stair stringers from total rise and run — the calculator solves the right triangle instantly.","Concrete in cubic yards from slab dimensions — the order quantity without conversion errors."],"history":["Construction Master (1978) created the category; it remains the job-site standard.","Trade-specific keys beat general math for speed and error reduction."],"points":["Feet-inch-fraction entry — dimensions as spoken.","Right-triangle solutions: stairs, rafters, bracing.","Area/volume in trade units: square feet, roofing squares, cubic yards.","Material estimating: studs, sheets, blocks from dimensions.","The orange standard: the recognizable job-site tool."],"qa":[["Why not use a scientific calculator?","Trade units: feet-inches-fractions need native support — decimals invite errors."],["What is a roofing square?","100 sq ft — the roofing trade's unit."],["How are stairs computed?","Right triangle from total rise/run — riser count, tread depth, stringer length."]],"title":"Construction Calculators","uses":["Carpentry: dimension math.","Estimating: material takeoffs.","Concrete and roofing: trade units."]},{"brief":"Medical calculators compute doses and scores — high-stakes arithmetic with verification culture built in.","examples":["Weight-based dosing double-checked against protocol — the bedside verification.","A stroke-risk score guiding ER treatment — the number behind the protocol."],"history":["Nomograms and dosing cards → PDA apps → smartphones — each wave faster, each needing validation.","Regulation treats dosing software as medical devices."],"points":["Dosing: mg/kg with unit vigilance — the highest-stakes arithmetic.","Clinical scores: validated risk numbers guiding protocols.","IV rates: dimensional analysis as patient safety.","Verification: independent double-checks — the tool assists, humans decide.","Validation: formulas must be verified — wrong math injures."],"qa":[["What is the most dangerous calculation error?","Unit mixups — mg vs mcg is 1000×."],["What is a clinical score?","A validated formula converting findings into a treatment-guiding number."],["Can apps replace judgment?","Never — they compute; clinicians decide and verify."]],"title":"Medical Calculators","uses":["Bedside: dose verification.","Emergency: rapid scoring.","Pharmacy: compounding math."]},{"brief":"Statistical calculators are data machines — distributions, regressions, and inference — the AP Statistics and lab workhorse.","examples":["A biology student runs chi-square on genetics crosses — the p-value deciding the inheritance model.","A quality tech computes control limits from 25 subgroups — the line's voice."],"history":["Stats keys arrived with scientific calculators (1970s); graphing models absorbed the full curriculum.","The AP Stats exam assumes a capable stats calculator."],"points":["Descriptive: mean, SD, quartiles, box plots — the data's shape.","Distributions: normal, t, binomial, Poisson — probabilities and critical values.","Regression: linear through logistic — fits with diagnostics.","Inference: confidence intervals and tests — the decisions.","Data handling: lists, sorting, and outlier tools."],"qa":[["What stats does AP require?","1/2-var stats, regressions, distributions, inference — the graphing calculator covers it."],["What is a p-value on the device?","The tail probability from the test function — small p, reject the null."],["Why lists matter?","Datasets live in lists — clean data entry is half of stats."]],"title":"Statistical Calculators","uses":["Classes: AP Statistics.","Labs: experiment analysis.","Quality: SPC on the floor."]},{"brief":"Matrix calculators handle linear algebra — the mathematics of systems, graphics, and engineering — natively.","examples":["An engineer solves 4 equations in 4 unknowns — the matrix inverse doing the work.","A graphics student multiplies transformation matrices — the rotation composed."],"history":["Matrix functions came to handhelds in the 1980s; graphing calculators made them classroom tools.","Linear algebra's rise (data science, graphics) keeps them relevant."],"points":["Entry: matrix editors with dimension control.","Operations: add, multiply, inverse, transpose, determinant.","Solving: simultaneous equations via inverse or rref.","Eigenvalues on advanced models — the deeper linear algebra.","Applications: circuits, structures, graphics, Markov chains."],"qa":[["What is rref?","Reduced row-echelon form — the systematic solution of linear systems."],["Why matrices for graphics?","Transformations (rotate, scale, translate) compose as matrix products."],["When is a matrix not invertible?","Determinant zero — the system has no unique solution."]],"title":"Matrix Calculators","uses":["Engineering: systems of equations.","Graphics: transformations.","Data: linear models."]},{"brief":"Equation solvers find roots numerically — the answer when algebra can't deliver closed forms.","examples":["An engineer solves x³−2x−5=0: the solver iterates to 2.0946.","A finance student finds the rate equating payments to price — the yield solved."],"history":["Newton's method (17th century) became the solver's engine; handhelds automated it in the 1980s.","Modern solvers handle systems, not just single equations."],"points":["Single-variable: guess, iterate, converge — Newton and secant methods.","Systems: multiple equations, multiple unknowns — the advanced solvers.","Polynomial: all roots (real and complex) on capable models.","TVM as solver: the financial calculator is a specialized equation solver.","Convergence: good guesses matter — the solver needs a starting neighborhood."],"qa":[["How does a solver find roots?","Iterative methods (Newton): guess, improve via tangent, repeat until converged."],["What if it doesn't converge?","Better initial guess, or bracket the root — solvers need neighborhoods."],["What is the TVM solver?","Five variables, one equation — the financial calculator solving for whichever is unknown."]],"title":"Equation Solvers","uses":["Engineering: unsolvable-by-hand equations.","Finance: yields and rates.","Science: model fitting."]},{"brief":"Unit converter calculators translate measures — the dimensional discipline in a dedicated device or mode.","examples":["A machinist converts 0.875 in to mm: 22.225 — the tolerance math.","A traveler converts miles to kilometers for the rental car's speedometer."],"history":["Conversion tables → calculator keys → phone apps with live currency.","The Mars Orbiter ($125M) made conversion discipline famous."],"points":["Built-in: length, mass, temperature, pressure, energy — one key away.","Temperature's offset: °F↔°C needs the 32 — not a pure ratio.","Engineering: carry units always — the Orbiter's lesson.","Currency needs live rates — the phone beats the desk device.","Dimensional analysis: the method behind the key."],"qa":[["Why is temperature conversion special?","The offset: (F−32)×5/9 — most conversions are pure ratios."],["What killed the Mars Climate Orbiter?","Metric/imperial mismatch — thruster data in mismatched units."],["How do professionals avoid unit errors?","Carrying units through every step — dimensional analysis."]],"title":"Unit Converter Calculators","uses":["Travel: measures and money abroad.","Shops: metric/imperial work.","Engineering: unit discipline."]},{"brief":"Currency and travel calculators handle money across borders — rates, conversions, and trip budgets.","examples":["A €60 dinner: the converter shows $64.80 at today's rate — the spending reality.","A two-week trip budget in three currencies — the envelope math."],"history":["Paper rate tables → electronic converters → live phone apps.","Multi-currency cards reduced the traveler's conversion burden."],"points":["Live rates: the phone's advantage — markets move.","Cash vs card rates differ — the spread is the cost.","Trip budgets: per-day allowances per currency.","Tipping norms per country — the cultural layer.","Offline mode: downloaded rates where networks fail."],"qa":[["Why do rates differ by source?","Spreads: each provider marks up — compare the all-in cost."],["Cash or card abroad?","Cards usually win on rate; cash for the cash-only world — carry both."],["What is dynamic currency conversion?","Paying in home currency abroad — usually a bad rate; choose local."]],"title":"Currency and Travel Calculators","uses":["Travel: spending clarity.","Business: expense estimates.","Shopping: cross-border prices."]},{"brief":"Kitchen calculators scale recipes and convert units — the culinary math of servings and pans.","examples":["Thanksgiving for 14: the 8-serving recipe × 1.75 — every ingredient scaled.","Grams from cups: 250g flour, not 2 cups — the baker's precision."],"history":["Cooks estimated for centuries; digital scales and apps made precision easy.","Baker's percentages professionalized scaling."],"points":["Serving scaling: multiply by the ratio — weight for accuracy.","Volume↔weight: the conversion tables — cups lie, grams don't.","Pan changes: area/volume ratios — the geometry of baking.","Baker's percentages: flour=100% — any batch size from one formula.","Timers and conversions built into kitchen devices."],"qa":[["Why weigh ingredients?","Precision and scalability — volume varies, weight doesn't."],["How do you change pan sizes?","Scale by area (cakes) or volume (batters)."],["What are baker's percentages?","Ingredients as % of flour — infinite scaling from one ratio set."]],"title":"Kitchen Calculators","uses":["Cooking: scaling and converting.","Baking: precision ratios.","Meal prep: bulk math."]},{"brief":"Kids' learning calculators teach arithmetic — big keys, friendly design, and teacher-approved limits.","examples":["A second-grader checks addition facts — the calculator as tutor, not crutch.","A classroom set of four-bangers: 30 identical devices, one lesson."],"history":["Debates since the 1970s: tool vs crutch — resolved as fluency-first.","Modern designs add games and exploration modes."],"points":["Fluency-first: facts before devices — the pedagogical rule.","Big keys, simple layouts — designed for small hands.","Teacher controls: some models limit functions per lesson.","Exploration: pattern-finding with the tool — math as discovery.","Classroom sets: identical, durable, affordable."],"qa":[["Do calculators hurt learning?","Not after fluency — they enable exploration beyond drill."],["What is fluency-first?","Master facts mentally, then automate — the tool extends, not replaces."],["Why identical classroom sets?","Fairness and teachability — one lesson, one device behavior."]],"title":"Kids and Learning Calculators","uses":["Elementary: supervised exploration.","Classrooms: standardized sets.","Home: homework checking."]},{"brief":"Large-display and accessible calculators serve low vision and motor needs — independence through design.","examples":["A senior's jumbo-key calculator with 2× digits — the bills paid independently.","A talking calculator confirming entries aloud — errors caught by ear."],"history":["Talking calculators (1980s) pioneered; large-display models followed; accessibility law broadened the market.","Voice assistants added a new hands-free path."],"points":["Jumbo digits: high-contrast, 2× height — the low-vision essential.","Talking output: speech confirmation — independence for blind users.","Big tactile keys: operable with limited dexterity.","Exam accommodations: approved accessible models exist.","Voice math: the newest alternative — spoken questions, spoken answers."],"qa":[["What helps low vision most?","Large high-contrast digits plus talking confirmation."],["Are they exam-legal?","Approved accessible models are increasingly listed."],["What about voice assistants?","Hands-free math — a growing alternative."]],"title":"Large-Display and Accessible Calculators","uses":["Seniors: independent finances.","Low vision: readable computation.","Workplace: accommodations."]},{"brief":"Watch and wearable calculators put arithmetic on the wrist — novelty with genuine convenience.","examples":["A quick tip computation on the watch — the phone stays pocketed.","A nurse's wearable timer-calculator for drip-rate checks."],"history":["Calculator watches (1970s-80s, Casio) were icons; smartwatches revived the idea with voice.","The novelty endures — convenience in miniature."],"points":["Wrist convenience: the always-there calculator.","Voice input: speak the math — the wearable's real interface.","Limits: tiny screens, simple functions — the physics of the wrist.","Smartwatch apps: scientific modes a tap away.","The verdict: convenience device, not a replacement."],"qa":[["Why a calculator on a watch?","Immediacy — the fastest path from question to answer."],["What are the limits?","Screen size and input — complex math stays on bigger devices."],["Is voice the real interface?","Yes — speaking math beats tapping a 1-inch screen."]],"title":"Watch and Wearable Calculators","uses":["Quick math: tips and conversions.","Convenience: the always-present tool.","Novelty: the enduring icon."]},{"brief":"Software and emulator calculators recreate classics on modern devices — the HP 41C on your phone, pixel-perfect.","examples":["An engineer runs a 1985 HP-15C emulator — the beloved keystrokes, immortal.","A student tries RPN free via an emulator before buying the real 12C."],"history":["Emulators preserved calculator history as hardware died; manufacturers now sell official apps.","The apps often cost less than the hardware they replace."],"points":["Faithful emulation: the original ROM running virtually — bugs included.","Official apps: manufacturers' own iOS/Android versions.","Free alternatives: open emulators for classic models.","Advantages: cheap, backed up, always present.","Limits: exams ban phones — the hardware still rules test day."],"qa":[["What is a calculator emulator?","Software recreating a classic calculator's behavior — often running its original code."],["Why emulate instead of buying?","Cost and convenience — try before you buy, or preserve a discontinued model."],["Are emulator apps exam-legal?","No — exams ban phones; the physical device is required."]],"title":"Software and Emulator Calculators","uses":["Enthusiasts: classic models preserved.","Trial: test-driving before buying.","History: the museum in your pocket."]},{"brief":"Calculators add in binary — half-adders and full-adders built from logic gates — the digital foundation under every sum.","examples":["5 + 3: 101 + 011 = 1000 — the gates ripple the carry, 8 appears.","A 64-bit adder chains 64 full-adders — billions of additions per second in a CPU."],"history":["Leibniz dreamed binary arithmetic (1703); Boole algebraized logic (1854); Shannon (1937) mapped logic to circuits.","Every chip since contains adders — the atom of computation."],"points":["Half-adder: XOR gives the sum bit, AND gives the carry — two gates, one bit.","Full-adder: adds two bits plus a carry-in — chainable to any width.","Ripple-carry: simple but slow — the carry ripples bit by bit.","Carry lookahead: computing carries in parallel — the speed trick.","Subtraction via two's complement: add the negated number — one circuit, both operations."],"qa":[["What is a half-adder?","A circuit adding two bits: XOR for sum, AND for carry."],["How do calculators subtract?","Two's complement: negate the subtrahend, then add — no separate subtractor needed."],["Why is addition the foundation?","Multiplication, division, and more all reduce to additions — the atom of arithmetic."]],"title":"How Calculators Add: Binary Adders","uses":["Chip design: the fundamental circuit.","Education: digital logic courses.","Understanding: what computation really is."]},{"brief":"CORDIC — the algorithm that computes trig on calculators — rotates vectors with only shifts and adds, no multiplier needed.","examples":["sin(30°): CORDIC rotates a unit vector by 30° in tiny steps — 0.5 emerges.","A 1970s calculator chip with no hardware multiplier still did trig — CORDIC made it possible."],"history":["Volder (1959) invented CORDIC for navigation computers; HP adopted it for calculators (1970s).","It remains in FPGAs and embedded systems — the multiplier-free trig."],"points":["Rotate by precomputed angles: each step halves the remaining angle — converging on the target.","Only shifts and adds: each micro-rotation is a shift-and-add — cheap in hardware.","Modes: rotation (compute sin/cos) and vectoring (compute angle/magnitude).","Beyond trig: hyperbolic, logs, square roots — the unified algorithm.","Why it mattered: multipliers were expensive silicon — CORDIC did more with less."],"qa":[["What does CORDIC stand for?","COordinate Rotation DIgital Computer — trig by rotating vectors."],["Why not just use series?","Series need multiplications; CORDIC needs only shifts and adds — cheaper in early hardware."],["Where is CORDIC still used?","FPGAs, embedded systems, and anywhere multipliers are scarce."]],"title":"CORDIC: The Trig Algorithm","uses":["Calculator history: how early chips did trig.","Embedded: multiplier-free math.","Education: algorithms in hardware."]},{"brief":"Taylor series compute sin, cos, and exp on calculators — infinite polynomials truncated to the needed precision.","examples":["sin(x) = x − x³/6 + x⁵/120 − ... — five terms give 7-digit accuracy for small x.","e^1: 1 + 1 + 1/2 + 1/6 + ... converging to 2.71828."],"history":["Taylor (1715) and Maclaurin formalized series; calculators used them where CORDIC didn't fit.","Range reduction (shrinking x first) makes series practical."],"points":["The idea: smooth functions equal their infinite polynomial — truncate for approximation.","Range reduction: shrink x into a small interval first — fewer terms needed.","Convergence: terms shrink fast for small x — the practical requirement.","Error bounds: the next term bounds the error — rigor, not hope.","Modern use: series still compute exp/log where CORDIC is awkward."],"qa":[["What is a Taylor series?","A function's infinite polynomial expansion — truncated, it approximates the function."],["Why reduce the range first?","Series converge fast only for small inputs — shrink x, compute, then adjust."],["How many terms for calculator accuracy?","A dozen-ish for 10-digit precision on reduced ranges."]],"title":"Taylor Series in Calculators","uses":["Numerical methods: the approximation foundation.","Calculator design: function implementation.","Education: calculus made computational."]},{"brief":"Logarithm algorithms — turning multiplication into addition inside the machine — power the log keys.","examples":["log₁₀(1000): the algorithm finds 3 — by scaling and series.","ln(x): computed via log₂ or atanh series after range reduction."],"history":["Briggs' tables (1617) were the original algorithm; calculators use series and CORDIC variants.","Log identities (log ab = log a + log b) structure every implementation."],"points":["Range reduction: write x = m × 2^k, then log x = log m + k·log 2 — small m, easy series.","Series for ln(1+t): alternating, converging for small t.","CORDIC hyperbolic mode: another path to logs.","Change of base: one good log gives all — log_b from ln.","Why logs matter: the keys to growth, decay, and scale."],"qa":[["How does a calculator compute ln?","Range-reduce to a small interval, apply a converging series, then reconstruct."],["What is range reduction?","Rewriting x = m × 2^k so the series sees only the small m."],["Why was log historically important?","It turned multiplication into addition — the slide rule's and navigator's power."]],"title":"Logarithm Algorithms","uses":["Calculator internals: the log key.","Numerical libraries: the same math.","History: how tables were computed."]},{"brief":"Square-root algorithms — Newton iteration converging quadratically — deliver roots in a handful of steps.","examples":["√2: guess 1.5 → 1.4167 → 1.41422 — three iterations, six digits.","A calculator's √ key: Newton under the hood since the 1970s."],"history":["Babylonian method (1800 BCE!) is Newton for roots; Newton formalized iteration (1669).","The famous fast inverse square root (Quake III) is Newton refined."],"points":["Newton for √a: x ← (x + a/x)/2 — average the guess with a/guess.","Quadratic convergence: correct digits double each step — blindingly fast.","Initial guess: any positive number works — convergence is robust.","Generalization: nth roots via x ← ((n−1)x + a/x^(n−1))/n.","Hardware: some chips have sqrt instructions — Newton in silicon."],"qa":[["How does Newton find square roots?","Iterate x = (x + a/x)/2 — each step roughly doubles correct digits."],["Why does it converge so fast?","Quadratic convergence — the error squares (shrinks) each iteration."],["What was the Babylonian method?","The same iteration, 3,700 years before Newton — discovered on clay tablets."]],"title":"Square Root Algorithms","uses":["Calculator keys: the √ implementation.","Graphics: normalizing vectors.","Embedded: division-free normalization."]},{"brief":"IEEE 754 floating point — the standard behind every calculator and computer — trades exactness for range.","examples":["0.1 + 0.2 = 0.30000000000000004 — the famous artifact of binary floating point.","1e308: the enormous range — from atoms to galaxies in 64 bits."],"history":["Chaos before 1985: every machine differed; IEEE 754 (Kahan et al.) unified arithmetic.","Calculators often use BCD/decimal instead — money needs exactness."],"points":["Format: sign, exponent, mantissa — scientific notation in binary.","Precision: ~7 digits (32-bit), ~16 (64-bit) — the mantissa's width.","Specials: infinities, NaN, signed zero — the edge cases standardized.","Rounding modes: to-nearest-even default — unbiased.","Why not for money: binary can't do 0.1 — decimal types (or integers of cents) for finance."],"qa":[["Why can't floating point do 0.1 exactly?","0.1 is repeating in binary — like 1/3 in decimal — so it's approximated."],["What is NaN?","Not a Number — the result of 0/0 and friends, propagating through calculations."],["Do calculators use IEEE 754?","Many use decimal/BCD instead — exact decimal arithmetic suits calculators."]],"title":"Floating Point: IEEE 754","uses":["Computing: the universal real-number format.","Science: range for the cosmos.","Education: why 0.1+0.2 surprises."]},{"brief":"Fixed-point arithmetic — the decimal point fixed by convention — gives exactness where floating point wavers.","examples":["Cents as integers: $19.99 = 1999 cents — exact money math, no 0.1 problem.","Embedded sensors: 16.16 fixed-point — deterministic real-time math."],"history":["Before floating-point hardware, fixed-point ruled; it survives where determinism matters.","Financial systems still count cents as integers."],"points":["The idea: scale by a fixed factor (100 for cents) — integers underneath.","Exactness: decimal cents are exact — no binary representation error.","Range vs precision: the scale factor trades one for the other.","Embedded: deterministic timing — no FPU needed.","Modern use: money, DSP, and real-time systems."],"qa":[["Why count cents instead of dollars?","Integers are exact — $19.99 as 1999 cents never has floating-point error."],["Where is fixed-point still used?","Embedded systems, DSP, and finance — determinism and exactness."],["What is the tradeoff?","Range: the fixed scale limits how large and how precise — chosen per application."]],"title":"Fixed-Point Arithmetic","uses":["Finance: exact money math.","Embedded: deterministic real-time.","DSP: signal processing."]},{"brief":"BCD — Binary Coded Decimal — stores each decimal digit in 4 bits: the calculator's way of thinking in tens.","examples":["19.99 in BCD: 0001 1001 . 1001 1001 — each digit its own nibble.","A calculator's display driver reads BCD directly — the digits are already decimal."],"history":["BCD predates binary floating point in business machines; calculators kept it for exact decimals.","x86 still has BCD instructions — the legacy in your CPU."],"points":["Encoding: 4 bits per digit (0000-1001) — wasteful but decimal-exact.","Why calculators: display and entry are decimal — BCD skips conversion.","Arithmetic: BCD adders with decimal adjust — hardware or software.","The 0.1 problem solved: decimal fractions are exact in BCD.","Tradeoff: 20% storage waste vs binary — worth it for exactness."],"qa":[["What is BCD?","Binary-Coded Decimal: each decimal digit in 4 bits — decimal-exact storage."],["Why do calculators use BCD?","Exact decimal arithmetic — 0.1 + 0.2 = 0.3, as users expect."],["Is BCD still used?","In calculators, financial systems, and anywhere decimals must be exact."]],"title":"BCD: Thinking in Tens","uses":["Calculators: exact decimal keys.","Finance: decimal-exact systems.","Displays: digit-direct driving."]},{"brief":"Order-of-operations implementation — how calculators parse 2+3×4 — ranges from immediate execution to full expression parsers.","examples":["2+3×4: chain gives 20, algebraic gives 14 — the parser decides.","(2+3)×(4+5): parentheses handled by recursive parsing — the expression tree."],"history":["Early calculators executed immediately (chain); AOS added hierarchy; textbook display made it visual.","Shunting-yard (Dijkstra, 1961) is the classic parser algorithm."],"points":["Immediate execution: operate as entered — simple, surprising.","AOS: precedence-aware with pending operations — TI's approach.","Expression trees: parse to a tree, then evaluate — the general solution.","Shunting-yard: Dijkstra's algorithm converting infix to RPN for evaluation.","Parentheses: the user's override — respected by every system."],"qa":[["Why do calculators disagree on 2+3×4?","Different parsing: immediate (20) vs precedence-aware (14)."],["What is the shunting-yard algorithm?","Dijkstra's method converting infix expressions to RPN using operator precedence."],["Which is correct?","Precedence-aware (14) matches mathematics — but know your device."]],"title":"Order of Operations Inside","uses":["Calculator design: the parser.","Education: why devices differ.","Programming: expression evaluation."]},{"brief":"Stack-based evaluation — RPN's engine — computes with a last-in-first-out stack: the elegant heart of HP calculators.","examples":["3 4 + 5 ×: push 3, push 4, + → 7, push 5, × → 35 — the stack choreography.","(2+3)×(4+5): RPN 2 3 + 4 5 + × — no parentheses needed."],"history":["Łukasiewicz's notation (1920s); Hamblin named RPN (1950s); HP-35 (1972) made it famous.","Forth and PostScript are stack languages — RPN grown up."],"points":["The stack: push operands, operators pop and push results — LIFO.","Four levels (X,Y,Z,T) on classic HPs — enough for real problems.","No parentheses: the stack order encodes nesting.","Visibility: the stack shows intermediates — the anti-black-box.","Beyond calculators: Forth, PostScript, JVM — stacks everywhere."],"qa":[["How does the stack evaluate 3 4 +?","Push 3, push 4, + pops both and pushes 7."],["Why is stack evaluation elegant?","No precedence rules, no parentheses — the order is the meaning."],["Where else are stacks used?","Forth, PostScript, the JVM, and function calls — computing's favorite structure."]],"title":"Stack-Based Evaluation","uses":["RPN calculators: the engine.","Language design: Forth and PostScript.","Education: how evaluation works."]},{"brief":"Parsing mathematical expressions — turning keystrokes into computation — is the calculator's language processing.","examples":["2+3×4 parsed to a tree: + at root, × below — evaluation follows the tree.","sin(30)+2: the parser handles functions, nesting, and precedence uniformly."],"history":["Grammars (Chomsky, 1950s) formalized languages; Dijkstra's shunting-yard (1961) parses expressions.","Every calculator and compiler since uses these ideas."],"points":["Tokenizing: keystrokes become tokens — numbers, operators, functions.","Grammars: rules defining valid expressions — the syntax law.","Shunting-yard: infix to postfix via precedence — Dijkstra's elegant algorithm.","Trees: parsed expressions become evaluation trees.","Errors: the parser reports mismatched parentheses and bad syntax — the error messages."],"qa":[["What is tokenizing?","Breaking input into meaningful pieces — numbers, operators — before parsing."],["What is the shunting-yard algorithm?","Converting infix to RPN respecting precedence — the classic expression parser."],["Why do calculators show syntax errors?","The parser rejected the input — usually parentheses or misplaced operators."]],"title":"Parsing Mathematical Expressions","uses":["Calculator design: the input engine.","Compilers: the same theory.","Education: languages have grammar."]},{"brief":"Numerical integration on calculators — Simpson, Gauss quadrature — computes definite integrals without antiderivatives.","examples":["∫₀¹ e^(-x²)dx: no elementary antiderivative — the calculator's quadrature gives 0.7468.","A physics student integrates acceleration data — velocity from the area under the curve."],"history":["Simpson (1743) and Gauss (1814) gave the rules; calculators automated them (1980s).","Adaptive quadrature refines where the function wiggles."],"points":["Riemann sums: the idea — rectangles under the curve.","Simpson's rule: parabolas through triplets — accurate and simple.","Gauss quadrature: optimal points — fewer evaluations, high accuracy.","Adaptive: subdivide where error is high — effort where needed.","When it fails: singularities and wild oscillation — know the limits."],"qa":[["What is Simpson's rule?","Approximating the integral with parabolas through successive triplets of points."],["Why adaptive quadrature?","It subdivides only where the function is difficult — efficient accuracy."],["When does numerical integration fail?","Singularities, discontinuities, and extreme oscillation — the hard cases."]],"title":"Numerical Integration","uses":["Physics: areas under data.","Engineering: totals from rates.","Calculus classes: the numeric path."]},{"brief":"Root-finding — Newton-Raphson and bisection — solves equations the calculator can't rearrange.","examples":["x³−2x−5=0: Newton from x=2 converges to 2.0946 in 4 steps.","A solver brackets a root between sign changes — bisection's guarantee."],"history":["Newton (1669), Raphson (1690); bisection is ancient common sense formalized.","Every solver key uses these — the hidden workhorses."],"points":["Bisection: halve the bracket — slow, certain, linear convergence.","Newton: follow the tangent — fast (quadratic) but needs good starts and derivatives.","Secant: Newton's derivative-free cousin — two points define the slope.","Convergence: tolerance and max iterations — the stopping rules.","Failure modes: flat spots, cycles, and wrong basins — the solver's bad days."],"qa":[["How does Newton-Raphson work?","Iterate x − f(x)/f′(x) — follow the tangent to the root."],["Why use bisection if it's slow?","Certainty: it always converges on a bracketed sign change."],["What makes solvers fail?","Bad initial guesses, flat derivatives, and multiple roots — the classic trio."]],"title":"Root Finding: Newton-Raphson","uses":["Solvers: the engine behind the key.","Engineering: implicit equations.","Finance: yield solving."]},{"brief":"Matrix operation internals — the algorithms behind the MATRX menu — from multiplication to decompositions.","examples":["A 3×3 inverse via Gauss-Jordan — the calculator's row operations.","Solving Ax=b by LU decomposition — factor once, solve many."],"history":["Gauss elimination (ancient/19th century); numerical analysts (1950s-70s) made it stable.","LAPACK codified the best algorithms — calculators use the small cases."],"points":["Multiplication: the O(n³) triple loop — the cost center.","Gauss-Jordan: row-reduce to inverse — the teaching algorithm.","LU decomposition: factor into triangular — efficient repeated solving.","Determinants: via elimination — the singularity test.","Stability: partial pivoting — the numerical hygiene."],"qa":[["What is LU decomposition?","Factoring A into lower×upper triangular — then solving is two easy triangular solves."],["Why pivot?","Avoiding division by tiny numbers — numerical stability."],["How expensive is matrix math?","Roughly cubic in size — 100×100 is a million operations."]],"title":"Matrix Operation Internals","uses":["Engineering: systems solving.","Graphics: transforms.","Data: least squares."]},{"brief":"Statistical algorithms — the math behind the STAT menu — from means to regressions computed stably.","examples":["Standard deviation via two-pass algorithm — the numerically stable way.","Linear regression: the normal equations or QR — the best-fit line."],"history":["Computing formulas (1960s) replaced desk-calculator methods; stable algorithms (1970s) fixed the naive ones.","The calculator's stats are real numerical analysis."],"points":["Mean and variance: two-pass or Welford's — stability matters.","Regression: least squares via normal equations — minimizing squared error.","Correlation: the normalized covariance — strength of linear relation.","Distributions: approximations (Abramowitz-Stegun) — the p-values.","Randomness: the algorithms need good RNGs — statistics' fuel."],"qa":[["What is Welford's algorithm?","One-pass stable mean/variance — avoiding catastrophic cancellation."],["How is regression computed?","Least squares: minimizing vertical squared errors — via normal equations."],["Why do p-values need approximations?","No closed forms for normal tails — rational approximations deliver them."]],"title":"Statistical Algorithms","uses":["Stats keys: the real math.","Science: data analysis.","Quality: SPC computations."]},{"brief":"Random number generation — pseudorandom algorithms seeding simulations — the calculator's dice.","examples":["Monte Carlo π: random points in a square — the fraction in the circle estimates π.","A stats class simulates sampling distributions — the RNG as teacher."],"history":["Von Neumann's middle-square (1946) was flawed; linear congruential generators ruled; Mersenne Twister (1997) modernized.","True randomness comes from hardware — quantum and thermal noise."],"points":["Pseudorandom: deterministic sequences that look random — seedable, repeatable.","LCG: x = (ax+c) mod m — simple, flawed, historic.","Quality: period length and statistical tests — the diehard suites.","Seeding: the seed fixes the sequence — reproducibility for science.","True RNG: hardware entropy — unpredictable, unrepeatable."],"qa":[["Are calculator random numbers truly random?","No — pseudorandom: deterministic from a seed, statistically random-looking."],["Why does seeding matter?","Reproducibility: same seed, same sequence — science demands it."],["What makes a good RNG?","Long period, uniformity, and passing statistical tests."]],"title":"Random Number Generation","uses":["Simulations: Monte Carlo methods.","Statistics: resampling.","Games: dice and shuffles."]},{"brief":"Prime number functions — testing and finding primes — the number theory on advanced calculators.","examples":["Is 104729 prime? Miller-Rabin says yes — probabilistic but certain enough.","The 10,000th prime: sieves generate, tests verify."],"history":["Eratosthenes' sieve (~200 BCE) still teaches; Miller-Rabin (1980) made testing fast.","RSA (1977) made primes the guardians of the internet."],"points":["Trial division: the naive test — fine for small numbers.","Sieve of Eratosthenes: generating all primes to n — ancient and efficient.","Miller-Rabin: probabilistic, practically certain — the workhorse test.","Prime gaps and distribution: the deep waters — Riemann's shadow.","Why primes matter: RSA encryption — internet security's foundation."],"qa":[["How do you test primality quickly?","Miller-Rabin: probabilistic, fast, practically certain."],["What is the Sieve of Eratosthenes?","Crossing out multiples — the remaining numbers are prime."],["Why are primes important?","RSA: multiplying primes is easy, factoring is hard — encryption's asymmetry."]],"title":"Prime Number Functions","uses":["Cryptography: RSA key generation.","Education: number theory.","Computing: hashing and algorithms."]},{"brief":"GCD and LCM algorithms — Euclid's ancient method still the fastest way to reduce fractions and find common ground.","examples":["Reduce 48/180: GCD is 12 → 4/15 — Euclid's algorithm in two steps.","LCM of 12 and 18: 36 — the common denominator."],"history":["Euclid (~300 BCE) gave the algorithm; it remains the model of elegant computation.","Binary GCD (Stein) optimizes for computers."],"points":["Euclid: GCD(a,b) = GCD(b, a mod b) — repeat until zero.","Why it's fast: logarithmic steps — 2,000 years unbeaten in essence.","LCM from GCD: lcm = a×b/gcd — the relationship.","Fractions: GCD reduces, LCM finds common denominators.","Extended Euclid: also finds modular inverses — cryptography's tool."],"qa":[["How does Euclid's algorithm work?","Replace (a,b) with (b, a mod b) until remainder zero — the last nonzero is the GCD."],["What is the LCM-GCD relationship?","lcm(a,b) × gcd(a,b) = a × b."],["Why is Euclid still taught?","It's the perfect algorithm: ancient, simple, optimal — a timeless lesson."]],"title":"GCD and LCM Algorithms","uses":["Fractions: reduction and denominators.","Cryptography: modular inverses.","Scheduling: coinciding cycles."]},{"brief":"Base conversion algorithms — the math shifting numbers between binary, decimal, and hex.","examples":["255 → hex: divide by 16 repeatedly — FF emerges.","0xFF → binary: each hex digit expands to 4 bits — 11111111."],"history":["Positional bases are ancient (Babylonian 60); binary conversion algorithms came with computing.","Programmer calculators made conversion a keystroke."],"points":["To decimal: positional sum — digits × base^position.","From decimal: repeated division — remainders reversed.","Hex-binary: direct 4-bit mapping — the programmer's shortcut.","Fractions: repeated multiplication — the fractional mirror.","Why bases matter: humans think decimal, machines binary, programmers hex."],"qa":[["How do you convert decimal to hex?","Repeated division by 16 — remainders (A-F for 10-15) read backwards."],["Why is hex-binary conversion trivial?","16 = 2⁴ — each hex digit is exactly 4 bits."],["How do fractions convert bases?","Repeated multiplication by the base — integer parts become the digits."]],"title":"Base Conversion Algorithms","uses":["Programming: hex and binary fluency.","Networking: address math.","Education: number systems."]},{"brief":"Fraction arithmetic internals — exact rational computation — how calculators keep 1/3 exact.","examples":["1/3 + 1/6 = 1/2 exactly — numerator/denominator pairs, no decimals.","A CAS keeps √2 symbolic — exactness beyond rationals."],"history":["Exact rational arithmetic is ancient; calculators made it a display mode (1980s).","Symbolic systems generalize exactness to all of math."],"points":["Representation: numerator/denominator pairs — reduced by GCD.","Operations: cross-multiplication with reduction — exact, always.","Mixed numbers: the display form — improper underneath.","Limits: numerators grow — big integers needed for long chains.","Beyond: symbolic systems keep π, √2, e exact — the CAS promise."],"qa":[["How do calculators keep fractions exact?","Numerator/denominator pairs reduced by GCD — no decimal approximation."],["Why do numerators grow?","Repeated operations multiply denominators — big-integer support handles it."],["What is exact computation's limit?","Irrationals need symbols — rationals alone can't express √2."]],"title":"Fraction Arithmetic Internals","uses":["Education: exact fraction work.","CAS: symbolic exactness.","Precision: when decimals won't do."]},{"brief":"Complex number support — a+bi arithmetic on calculators — brings electrical engineering and quantum math to the handheld.","examples":["AC impedance: 3+4i ohms — magnitude 5, angle 53° — the phasor math.","(2+3i)(1−i) = 5+i — the calculator handles the algebra."],"history":["Complex numbers (16th century, Cardano) took centuries to accept; electrical engineering (Steinmetz, 1890s) made them essential.","Calculators added complex modes in the 1980s."],"points":["Rectangular (a+bi) and polar (r∠θ) forms — the calculator converts freely.","Operations: add, multiply, divide, conjugate — the algebra automated.","Functions: complex trig, logs, powers — the full extension.","Applications: AC circuits, control systems, signal processing.","The display: results in either form — choose per problem."],"qa":[["What is a+bi?","A complex number: real part a, imaginary part bi, where i²=−1."],["Why do engineers use complex numbers?","AC circuits: impedance combines resistance and reactance as one complex number."],["What is polar form?","Magnitude and angle (r∠θ) — natural for rotations and waves."]],"title":"Complex Number Support","uses":["Electrical: AC analysis.","Physics: waves and quantum.","Math: the complete number system."]},{"brief":"Calculus functions — numeric derivatives and integrals — put analysis on the calculator.","examples":["d/dx(x³) at x=2: the calculator's symmetric difference gives 12.000 — the slope.","∫₀¹x²dx = 0.3333 — quadrature where antiderivatives are hard."],"history":["Numeric calculus is centuries old; calculators automated it (1980s); CAS added symbolic.","The AP Calculus exam assumes these tools."],"points":["Numeric derivatives: symmetric differences — (f(x+h)−f(x−h))/2h.","Numeric integrals: adaptive quadrature — the ∫dx key.","Graphical: tangent lines and shaded areas — calculus visualized.","Symbolic (CAS): exact derivatives and integrals — the deeper models.","Limits: numeric approach — the foundation made concrete."],"qa":[["How does a calculator differentiate?","Symmetric difference quotient — approximating the tangent slope numerically."],["What is adaptive quadrature?","Refining the integration mesh where the function varies most."],["Why learn calculus if calculators do it?","Understanding: the tool computes, but modeling and interpretation are human."]],"title":"Calculus Functions","uses":["Classes: AP Calculus tools.","Engineering: rates and totals.","Science: models from data."]},{"brief":"Differential equation solvers — Euler's method to Runge-Kutta — approximate the equations of motion and change.","examples":["A falling object with air resistance: Euler steps trace the velocity curve.","A spring-mass simulation: RK4 conserves energy far better than Euler."],"history":["Euler (1768) gave the first method; Runge-Kutta (1900) refined it; calculators brought it handheld.","Every physics engine uses these — games included."],"points":["Euler: step along the tangent — simple, crude, instructive.","Runge-Kutta (RK4): four evaluations per step — the workhorse.","Step size: smaller steps, better accuracy, more work — the tradeoff.","Stability: stiff equations need implicit methods — the advanced topic.","Applications: orbits, circuits, populations — change modeled."],"qa":[["What is Euler's method?","Stepping along the tangent: y += h·f(x,y) — simple, first-order."],["Why is RK4 better?","Four slope samples per step — fourth-order accuracy, the standard."],["What are stiff equations?","Equations with wildly different timescales — needing special implicit methods."]],"title":"Differential Equation Solvers","uses":["Physics: motion simulation.","Engineering: dynamic systems.","Education: seeing solutions evolve."]},{"brief":"Financial algorithm internals — how TVM keys actually solve — Newton on money-over-time equations.","examples":["Solving for rate: the calculator iterates the TVM equation — Newton's method on cash flows.","IRR: the rate zeroing NPV — found iteratively, bracketed first."],"history":["Interest tables were the original algorithm; calculators (1970s) iterated instead.","The 12C's solver is a masterclass in numeric finance."],"points":["TVM equation: one equation, five variables — solve for any.","Rate solving: iterative — no closed form exists.","IRR: NPV=0 solved by Newton/secant — multiple roots possible.","Amortization: scheduled arithmetic — exact, not iterative.","Day counts: 30/360 vs actual — conventions change answers."],"qa":[["How does the calculator find interest rate?","Iterative root-finding on the TVM equation — no formula exists."],["Can IRR have multiple answers?","Yes — unconventional cash flows can yield multiple rates; the calculator finds one."],["What are day-count conventions?","Rules (30/360, actual/actual) for interest accrual — the fine print."]],"title":"Financial Algorithm Internals","uses":["Banking: the math behind the keys.","Investing: IRR/NPV engines.","Education: finance theory."]},{"brief":"Date arithmetic algorithms — the calendar's irregular math — from Julian days to business-day counts.","examples":["Days between 2024-03-01 and 2026-10-12: Julian day numbers subtract cleanly.","45 business days from a start: skipping weekends and holidays — the settlement math."],"history":["Julian days (1583) simplified astronomy; business-day math grew with finance.","Programmers still curse date handling — the hardest 'simple' problem."],"points":["Julian day numbers: continuous day counts — differences by subtraction.","Leap rules: ÷4, except ÷100, except ÷400 — the Gregorian correction.","Business days: weekends plus holiday calendars — jurisdiction-specific.","Day counts: finance's 30/360 vs actual — the interest conventions.","Edge cases: time zones, DST, leap seconds — the programmer's nightmare."],"qa":[["What is a Julian day number?","Continuous count of days — date differences become simple subtraction."],["What is the leap-year rule?","Divisible by 4, except centuries, except ÷400 — 2000 was leap, 1900 wasn't."],["Why is date math hard?","Irregular months, leap years, time zones, DST — the calendar resists uniformity."]],"title":"Date Arithmetic Algorithms","uses":["Finance: settlements and accruals.","Project planning: deadline math.","Software: the eternal challenge."]},{"brief":"Checksum and validation algorithms — Luhn, ISBN, verhoeff — catch keying errors in numbers that matter.","examples":["A credit card's last digit: the Luhn check — mistyped numbers rejected instantly.","An ISBN-13's check digit: weighted sums catching transpositions."],"history":["Luhn (1954, IBM) patented the mod-10 check; ISBN adopted checks (1970s); verhoeff caught more errors.","Every account number carries its own proofreader."],"points":["Luhn: double alternate digits, sum, mod 10 — the credit-card guardian.","ISBN-13: weighted alternating 1/3 — the book identifier's check.","Verhoeff: dihedral-group math — catching transpositions Luhn misses.","Why checks: human keying errors are common — the digit is the safety net.","Calculators with check functions: the professional's verification."],"qa":[["How does the Luhn check work?","Double every second digit from the right, sum all digits, total mod 10 must be 0."],["What errors do checks catch?","Single-digit errors and most transpositions — the common keying mistakes."],["Why not just be careful?","Humans err; checks are cheap — defense in depth."]],"title":"Checksum and Validation Algorithms","uses":["Payments: card number validation.","Publishing: ISBN integrity.","Data entry: error catching."]},{"brief":"Calculator accuracy and error bounds — how wrong can the answer be — the honest accounting of computation.","examples":["A 10-digit calculator's trig: accurate to 9+ digits — the guard digits working.","Chained calculations: each step's rounding compounds — the error budget."],"history":["Wilkinson (1960s) founded rounding-error analysis; IEEE 754 standardized the behavior.","Interval arithmetic offers guaranteed bounds — the rigorous path."],"points":["Guard digits: extra internal precision — the visible digits stay correct.","Error accumulation: n operations, ~√n growth typically — the statistics of rounding.","Catastrophic cases: ill-conditioned problems — accuracy lost regardless.","Interval arithmetic: bounds instead of points — guaranteed enclosures.","The lesson: know your tool's limits — digits aren't truth."],"qa":[["What are guard digits?","Extra internal precision beyond displayed digits — absorbing rounding error."],["How fast does error accumulate?","Typically like √n for n operations — slowly, except in ill-conditioned cases."],["What is interval arithmetic?","Computing with bounds [lo,hi] — the answer guaranteed inside."]],"title":"Calculator Accuracy and Error Bounds","uses":["Engineering: trusting results.","Numerics: algorithm design.","Education: digits vs truth."]},{"brief":"Symbolic vs numeric computation — exact forms against decimal approximations — the two philosophies of machine math.","examples":["√2: symbolic keeps √2; numeric gives 1.41421356 — exact vs useful.","∫e^(-x²): symbolic fails (no elementary form); numeric gives 0.7468 — complementary strengths."],"history":["Numeric computing is ancient; symbolic (Macsyma 1968, Mathematica 1988) is younger.","CAS calculators (1990s) put both in the hand."],"points":["Numeric: fast, general, approximate — the engineer's default.","Symbolic: exact, insightful, limited — the mathematician's.","Hybrid: numeric where symbolic fails, symbolic where exactness matters.","The exam divide: numeric allowed, symbolic often banned — policy reflects pedagogy.","Future: AI blending both — the best of each, automatically."],"qa":[["What is the difference?","Numeric computes decimal approximations; symbolic manipulates exact mathematical forms."],["When is each better?","Numeric for answers, symbolic for insight — engineering vs mathematics."],["Will AI merge them?","It's starting: systems choosing exact or numeric per problem — the intelligent hybrid."]],"title":"Symbolic vs Numeric Computation","uses":["Math: choosing the right tool.","Engineering: answers that build.","Education: understanding vs computing."]},{"brief":"AI calculators — conversational math assistants — solve word problems, show reasoning, and check work.","examples":["A photo of a handwritten integral: the AI solves it, showing steps — the tutor in the camera.","A word problem described in speech: the AI models it, computes, and explains — math as conversation."],"history":["Photomath (2014) read printed math; LLMs (2020s) reason about word problems.","The calculator dissolves into the assistant."],"points":["Multimodal: photo, speech, handwriting — input however you think.","Reasoning shown: steps, not just answers — the tutor model.","Word problems: natural language to equations — the historic hard step.","Verification: AI checks hand work — the always-patient tutor.","The caveat: confident errors — verification skill matters more than ever."],"qa":[["Can AI solve word problems?","Increasingly yes — parsing language to math is the breakthrough."],["What is the biggest risk?","Plausible wrong answers — the fluency trap; always verify."],["Will AI replace learning math?","No — it changes what's valuable: modeling and verification over computation."]],"title":"AI Calculators: The Future","uses":["Education: tireless tutors.","Professionals: verified assistance.","Everyone: math as conversation."]},{"brief":"Choosing by type — the buyer's guide matching calculator to person, course, and career.","examples":["The nursing student: a basic scientific with dosage-friendly functions — the clinical choice.","The surveyor: a programmable with traverse routines — the field computer."],"history":["Choice exploded in the 1980s; exam lists now curate it.","The right tool beats the expensive tool — fit over features."],"points":["Students: match the syllabus and exam list — approval first.","Professionals: trade-specific models pay for themselves — construction, finance, medical.","Engineers: RPN or algebraic per tribe — plus the solver.","The minimalist: the phone covers basics — buy dedicated only for exams or durability.","Try before buying: emulators and store demos — the keystroke test."],"qa":[["What is the single best buying advice?","Match the requirement (exam/course/job) first — features second."],["Should you buy the most expensive?","Rarely — the $15 scientific does most math; pay for approval and fit."],["How do you test-drive?","Emulator apps and in-store demos — the keys must feel right."]],"title":"Choosing by Calculator Type","uses":["Students: the right approved model.","Professionals: trade-fit tools.","Buyers: fit over flash."]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
